{
  "suficiente": true,
  "diagnostico": "O sintoma descrito corresponde ao problema documentado em ch-08, onde o Outlook solicita a senha repetidamente mesmo após digitação correta, especialmente após troca de senha recente em ambiente corporativo.",
  "passos": [
    "Abrir as Credenciais do Windows e remover as entradas antigas do Outlook e do servidor de e-mail.",
    "Reiniciar o Outlook.",
    "Digitá-la nova senha com a opção de lembrar marcada."
  ],
  "fontes": [
    "ch-08"
  ]
}

{
  "suficiente": true,
  "diagnostico": "O cabo de rede está conectado fisicamente, mas a ausência da luz do conector indica que não há link elétrico estabelecido. Isso pode ser causado por um cabo defeituoso, uma tomada desligada no patch panel ou uma porta desabilitada no switch.",
  "passos": [
    "Verificar as luzes da placa de rede do computador.",
    "Trocar o cabo de conexão por um que se sabe estar bom.",
    "Testar o mesmo cabo em outra tomada ou em outro computador para isolar a falha.",
    "Conferir se a tomada está identificada e ligada no patch panel."
  ],
  "fontes": [
    "kb-rd-01"
  ]
}

